$(function(){$(".js-cookies-close").on("click",function(){var o=$(this).closest(".js-cookies");o.fadeOut(600,function(){Cookies.set("cookiesAccept",!0,{expires:365}),o.remove()})}),$(".js-horizontal-scroll-hint-container").each(function(){var i=$(this);i.data("cookie-name");i.find(".js-horizontal-scroll-hint").is(":hidden")||i.find(".icon-texts").on("scroll.hint",function(){var o=$(this);100<o.scrollLeft()&&i.find(".js-horizontal-scroll-hint").fadeOut(function(){o.off("scroll.hint")})})}),$(document).on("click",".js-target-show",function(){var o=$(this),i=$($(this).data("target"));i.length&&(o.toggleClass("is-rotate"),i.slideToggle(300))}),$(document).on("click",".js-sidebar-filters-open",function(){$("html").addClass("is-filters-open")}),$(document).on("click",".js-sidebar-filters-close",function(){$("html").removeClass("is-filters-open")})}),$(window).on("load",function(){});